// Starter file for Variables, Data Types, and Operators
// Task instructions:
// Write a script that declares variables of each primitive type, demonstrates type coercion with `==` vs `===`, and uses template literals to build a us...

solution_code:
// Variable declarations
const name = "Alice";       // Cannot be reassigned
let age = 25;               // Can be reassigned
age = 26;

// Primitive types
const str = "hello";                    // string
const num = 42;                         // number
const bool = true;                      // boolean
const undef = undefined;                // undefined
const nul = null;                       // null
const sym = Symbol("id");               // symbol

// Type coercion pitfalls
console.log(1 == "1");    // true  (coercion)
console.log(1 === "1");   // false (strict — preferred)
console.log(0 == false);  // true
console.log(0 === false); // false

// Template literals
const greeting = `Hello, ${name}! You are ${age}.`;

// Nullish coalescing (??) — only falls back for null/undefined
const displayName = name ?? "Anonymous";

// Optional chaining (?.)
const user = { profile: { email: "a@b.com" } };
console.log(user.profile?.email);   // "a@b.com"
console.log(user.address?.city);    // undefined (no error)

// Ternary operator
const status = age >= 18 ? "adult" : "minor";
